<?php require dirname(__DIR__).'/layouts/admin_start.php';$labels=['planned'=>'Planejada','in_progress'=>'Em andamento','completed'=>'Concluída','cancelled'=>'Cancelada'];$query=$_GET;unset($query['page']); ?>
<div class="validation-list">
<div class="validation-list-actions"><?php if(\BloodHub\Core\Permission::can('validations.create')): ?><a class="button button-primary" href="/validations/create">+ Nova validação</a><?php endif; ?></div>
<section class="validation-kpi-grid"><article><strong><?= (int)($kpis['planned']??0) ?></strong><span>Planejadas</span></article><article><strong><?= (int)($kpis['in_progress']??0) ?></strong><span>Em andamento</span></article><article><strong><?= (int)($kpis['completed']??0) ?></strong><span>Concluídas</span></article></section>
<section class="content-card validation-table-card"><form class="validation-filters" method="get"><label><span>PV</span><input name="pv_number" value="<?= htmlspecialchars($_GET['pv_number']??'') ?>"></label><label><span>Nome</span><input name="name" value="<?= htmlspecialchars($_GET['name']??'') ?>"></label><label><span>Unidade</span><select name="unit_id"><option value="">Todas</option><?php foreach($units as$unit): ?><option value="<?= (int)$unit['id'] ?>" <?= (int)($_GET['unit_id']??0)===(int)$unit['id']?'selected':'' ?>><?= htmlspecialchars($unit['name']) ?></option><?php endforeach; ?></select></label><label><span>Status</span><select name="status"><option value="">Todos</option><?php foreach($labels as$k=>$l): ?><option value="<?= $k ?>" <?= ($_GET['status']??'')===$k?'selected':'' ?>><?= $l ?></option><?php endforeach; ?></select></label><div class="validation-filter-actions"><button class="button">Filtrar</button><a class="button button-secondary" href="/validations">Limpar</a></div></form>
<div class="table-wrap"><table><thead><tr><th>PV</th><th>Nome</th><th>Unidade</th><th>Início</th><th>Previsão</th><th>Término</th><th>Status</th><th>Etapas</th><th>Amostras</th><th>Ações</th></tr></thead><tbody><?php foreach($validations as$v): ?><tr><td><strong><?= htmlspecialchars($v['pv_number']) ?></strong></td><td><?= htmlspecialchars($v['name']) ?></td><td><?= htmlspecialchars($v['unit_name']??'Unidade não definida') ?></td><td><?= date('d/m/Y',strtotime($v['start_date'])) ?></td><td><?= $v['expected_end_date']?date('d/m/Y',strtotime($v['expected_end_date'])):'—' ?></td><td><?= $v['actual_end_date']?date('d/m/Y',strtotime($v['actual_end_date'])):'—' ?></td><td><span class="status status-<?= $v['status'] ?>"><?= $labels[$v['status']] ?></span></td><td><?= (int)$v['phase_count'] ?></td><td><?= (int)$v['sample_count'] ?></td><td><div class="table-actions"><a class="table-action" href="/validations/view?id=<?= (int)$v['id'] ?>">Abrir</a><a class="table-action" href="/validations/dashboard?id=<?= (int)$v['id'] ?>">Dashboard</a><?php if(\BloodHub\Core\Permission::can('validations.edit')&&!in_array($v['status'],['completed','cancelled'],true)): ?><a class="table-action" href="/validations/edit?id=<?= (int)$v['id'] ?>">Editar</a><?php endif; ?></div></td></tr><?php endforeach; ?><?php if(!$validations): ?><tr><td colspan="10" class="empty">Nenhuma validação encontrada.</td></tr><?php endif; ?></tbody></table></div>
<?php if($total): ?><div class="validation-pagination"><span>Exibindo <?= ($page-1)*$perPage+1 ?>–<?= min($page*$perPage,$total) ?> de <?= $total ?> validações</span><nav><?php if($page>1): ?><a href="?<?= http_build_query($query+['page'=>$page-1]) ?>">Anterior</a><?php endif; ?><?php for($i=1;$i<=$pages;$i++): ?><a class="<?= $i===$page?'active':'' ?>" href="?<?= http_build_query($query+['page'=>$i]) ?>"><?= $i ?></a><?php endfor; ?><?php if($page<$pages): ?><a href="?<?= http_build_query($query+['page'=>$page+1]) ?>">Próxima</a><?php endif; ?></nav></div><?php endif; ?></section></div>
<?php require dirname(__DIR__).'/layouts/admin_end.php'; ?>
